//! Synthetic test signals generated by code (no binary fixtures).
#![allow(dead_code)]

use std::f64::consts::PI;

pub fn sine_wave(sr: u32, f: f64, secs: f64, amp: f32) -> Vec<f32> {
    let n = (sr as f64 * secs).round() as usize;
    (0..n).map(|i| amp * (2.0 * PI * f * i as f64 / sr as f64).sin() as f32).collect()
}

#[derive(Clone, Copy, Debug)]
pub enum Vowel {
    A,
    I,
    U,
}

impl Vowel {
    /// (formant centre Hz, bandwidth Hz) for the first three formants.
    pub fn formants(self) -> [(f64, f64); 3] {
        match self {
            Vowel::A => [(730.0, 90.0), (1090.0, 110.0), (2440.0, 160.0)],
            Vowel::I => [(270.0, 60.0), (2290.0, 100.0), (3010.0, 150.0)],
            Vowel::U => [(300.0, 60.0), (870.0, 90.0), (2240.0, 150.0)],
        }
    }
}

/// Per-sample f0 curve for a list of (f0, seconds) notes with 15 ms log-glides between notes,
/// plus optional sinusoidal vibrato (rate Hz, depth cents peak).
pub fn f0_curve(sr: u32, notes: &[(f64, f64)], vib_hz: f64, vib_cents: f64) -> Vec<f64> {
    let srf = sr as f64;
    let total: f64 = notes.iter().map(|n| n.1).sum();
    let n = (total * srf).round() as usize;
    let mut bounds = Vec::new();
    let mut t = 0.0;
    for nt in notes {
        bounds.push((t, t + nt.1, nt.0));
        t += nt.1;
    }
    let glide = 0.015;
    (0..n)
        .map(|i| {
            let t = i as f64 / srf;
            let k = bounds.iter().position(|b| t < b.1).unwrap_or(bounds.len() - 1);
            let mut lf = bounds[k].2.log2();
            // glide into this note from the previous one
            if k > 0 && t - bounds[k].0 < glide / 2.0 {
                let prev = bounds[k - 1].2.log2();
                let a = 0.5 + (t - bounds[k].0) / glide;
                lf = prev + (lf - prev) * a;
            } else if k + 1 < bounds.len() && bounds[k].1 - t < glide / 2.0 {
                let next = bounds[k + 1].2.log2();
                let a = 0.5 - (bounds[k].1 - t) / glide;
                lf += (next - lf) * a;
            }
            let vib = if vib_hz > 0.0 { vib_cents / 1200.0 * (2.0 * PI * vib_hz * t).sin() } else { 0.0 };
            2f64.powf(lf + vib)
        })
        .collect()
}

/// Glottal-pulse-like band-limited sawtooth following `f0` through three formant resonators.
pub fn vocal_from_curve(sr: u32, f0: &[f64], vowel: Vowel) -> Vec<f32> {
    let srf = sr as f64;
    let mut phase = 0.0f64;
    let mut src = Vec::with_capacity(f0.len());
    for &f in f0 {
        phase += 2.0 * PI * f / srf;
        if phase > 2.0 * PI {
            phase -= 2.0 * PI;
        }
        let kmax = ((0.45 * srf / f).floor() as usize).max(1);
        // Σ sin(kθ)/k via the Chebyshev recurrence
        let c2 = 2.0 * phase.cos();
        let (mut s1, mut s2) = (phase.sin(), 0.0f64);
        let mut acc = 0.0;
        for k in 1..=kmax {
            acc += s1 / k as f64;
            let s0 = c2 * s1 - s2;
            s2 = s1;
            s1 = s0;
        }
        src.push(acc);
    }
    let mut y = src;
    for (fc, bw) in vowel.formants() {
        let c = -(-2.0 * PI * bw / srf).exp();
        let b = 2.0 * (-PI * bw / srf).exp() * (2.0 * PI * fc / srf).cos();
        let a = 1.0 - b - c;
        let (mut y1, mut y2) = (0.0, 0.0);
        for v in y.iter_mut() {
            let o = a * *v + b * y1 + c * y2;
            y2 = y1;
            y1 = o;
            *v = o;
        }
    }
    // 10 ms fades and normalisation to 0.5 peak
    let fade = (0.01 * srf) as usize;
    let n = y.len();
    for i in 0..fade.min(n) {
        let g = i as f64 / fade as f64;
        y[i] *= g;
        y[n - 1 - i] *= g;
    }
    let peak = y.iter().fold(0.0f64, |m, v| m.max(v.abs())).max(1e-9);
    y.iter().map(|v| (0.5 * v / peak) as f32).collect()
}

/// Convenience: notes → vocal.
pub fn vocal(sr: u32, notes: &[(f64, f64)], vowel: Vowel, vib_hz: f64, vib_cents: f64) -> Vec<f32> {
    vocal_from_curve(sr, &f0_curve(sr, notes, vib_hz, vib_cents), vowel)
}

pub fn midi_hz(m: f64) -> f64 {
    440.0 * 2f64.powf((m - 69.0) / 12.0)
}

/// LPC formant estimate: autocorrelation LPC (order `p`) over Hamming-windowed,
/// pre-emphasised frames, envelope peaks of 1/|A(e^jw)| averaged over frames.
pub fn lpc_formants(x: &[f32], sr: u32, p: usize) -> Vec<f64> {
    let srf = sr as f64;
    let n = (0.05 * srf) as usize;
    let hop = n / 2;
    let mut env_acc = vec![0.0f64; 2048];
    let mut start = 0;
    let mut frames = 0;
    while start + n <= x.len() {
        let mut fr: Vec<f64> = (0..n)
            .map(|i| {
                let v = x[start + i] as f64 - if start + i > 0 { 0.97 * x[start + i - 1] as f64 } else { 0.0 };
                v * (0.54 - 0.46 * (2.0 * PI * i as f64 / (n - 1) as f64).cos())
            })
            .collect();
        let energy: f64 = fr.iter().map(|v| v * v).sum();
        if energy < 1e-8 {
            start += hop;
            continue;
        }
        // autocorrelation
        let r: Vec<f64> = (0..=p).map(|l| (0..n - l).map(|i| fr[i] * fr[i + l]).sum()).collect();
        // Levinson-Durbin
        let mut a = vec![0.0f64; p + 1];
        a[0] = 1.0;
        let mut e = r[0] * (1.0 + 1e-9);
        for i in 1..=p {
            let mut acc = r[i];
            for j in 1..i {
                acc += a[j] * r[i - j];
            }
            let k = -acc / e;
            let prev = a.clone();
            for j in 1..i {
                a[j] = prev[j] + k * prev[i - j];
            }
            a[i] = k;
            e *= 1.0 - k * k;
        }
        for (bi, acc) in env_acc.iter_mut().enumerate() {
            let w = PI * bi as f64 / 2048.0;
            let (mut re, mut im) = (0.0, 0.0);
            for (j, aj) in a.iter().enumerate() {
                re += aj * (w * j as f64).cos();
                im -= aj * (w * j as f64).sin();
            }
            *acc += -(re * re + im * im).ln();
        }
        frames += 1;
        fr.clear();
        start += hop;
    }
    let _ = frames;
    let mut peaks = Vec::new();
    for i in 1..env_acc.len() - 1 {
        if env_acc[i] > env_acc[i - 1] && env_acc[i] >= env_acc[i + 1] {
            let (a, b, c) = (env_acc[i - 1], env_acc[i], env_acc[i + 1]);
            let den = a - 2.0 * b + c;
            let off = if den.abs() > 1e-12 { 0.5 * (a - c) / den } else { 0.0 };
            let f = (i as f64 + off) * srf / 2.0 / 2048.0;
            if f > 150.0 {
                peaks.push(f);
            }
        }
    }
    peaks
}
